int post_json(const char *url, const char *body, const char *token) {
  char auth[512];
  snprintf(auth, sizeof auth, "Authorization: Bearer %s", token);
  CURL *curl = curl_easy_init();
  if (curl == NULL) return -1;
  struct curl_slist *headers = NULL;
  headers = curl_slist_append(headers, "Content-Type: application/json");
  headers = curl_slist_append(headers, auth);
  curl_easy_setopt(curl, CURLOPT_URL, url);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
  curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
  curl_slist_free_all(headers);
  CURLcode rc = curl_easy_perform(curl);
  curl_easy_cleanup(curl);
  return rc == CURLE_OK ? 0 : -1;
}

static struct curl_slist *append(struct curl_slist *list, const char *line) {
  struct curl_slist *next = curl_slist_append(list, line);
  if (next == NULL) curl_slist_free_all(list);
  return next;
}

int post_json(const char *url, const char *body, const char *token) {
  char auth[512];
  snprintf(auth, sizeof auth, "Authorization: Bearer %s", token);
  CURL *curl = curl_easy_init();
  if (curl == NULL) return -1;
  struct curl_slist *headers = append(NULL, "Content-Type: application/json");
  if (headers != NULL) headers = append(headers, auth);
  if (headers == NULL) {
    curl_easy_cleanup(curl);
    return -1;
  }
  curl_easy_setopt(curl, CURLOPT_URL, url);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
  curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
  CURLcode rc = curl_easy_perform(curl);
  curl_easy_cleanup(curl);
  curl_slist_free_all(headers);
  return rc == CURLE_OK ? 0 : -1;
}
